/**
 * Deterministic gate for the collision-probability slice.
 *
 * THE ORACLE IS MONTE CARLO, NOT A SECOND QUADRATURE
 *
 * The spec asks for a numerical integral over a disk. A gate that performed
 * the same integral with a finer mesh would mostly measure whether I can write
 * the same loop twice. So the reference draws samples from the same 2-D
 * Gaussian and counts the fraction landing inside the hard-body disk. Sampling
 * and quadrature share no step: one converges as 1/sqrt(N) by the law of large
 * numbers, the other as a mesh refinement. They agree only if both are right.
 *
 * Monte Carlo has sampling error, so every comparison below is made against
 * the MC standard error rather than a tolerance I chose to make a
 * disagreement go away. With p ~ 1e-2 and N = 4e6, that error is about 5e-5,
 * and the checks demand agreement within four of them.
 *
 * Sampling is seeded and deterministic. A gate whose verdict changes between
 * runs on unchanged code is not a gate — it is a coin flip that occasionally
 * blames the implementation.
 *
 * WHAT THIS GATE DOES NOT ESTABLISH
 *
 * That the probabilities mean anything operationally. They are computed from
 * an assumed uncertainty, because this project has no covariance data and
 * public TLEs carry none. The arithmetic is checked here; the assumption is
 * not, and cannot be. R7 exists so that caveat travels with the number, and
 * the last checks in this file are about the caveat rather than the maths.
 */

import { existsSync } from "node:fs";

function stackRoot(): string {
  const candidates = [
    process.env.DCODE_STACK,
    new URL("../../", import.meta.url).pathname,
    `${process.env.HOME}/dcode-stack`,
  ].filter(Boolean) as string[];
  for (const c of candidates) {
    const root = c.endsWith("/") ? c.slice(0, -1) : c;
    if (existsSync(`${root}/lib/invariants.ts`)) return root;
  }
  throw new Error("cannot locate the dcode-stack root; set DCODE_STACK");
}

const ROOT = stackRoot();
const { Checker } = await import(`${ROOT}/lib/invariants.ts`);

/** Deterministic uniform stream — mulberry32. */
function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Fraction of samples from N((missX, missZ), diag(sx², sz²)) that land within
 * `radius` of the origin, plus the standard error of that estimate.
 *
 * Box–Muller for the normal draws, which uses no library and no lookup table.
 */
function monteCarloPc(
  missX: number, missZ: number, sx: number, sz: number, radius: number,
  n = 4_000_000, seed = 0x5eed
): { p: number; se: number } {
  const u = rng(seed);
  let hits = 0;
  const r2 = radius * radius;
  for (let i = 0; i < n; i += 2) {
    const u1 = Math.max(u(), Number.MIN_VALUE);
    const u2 = u();
    const mag = Math.sqrt(-2 * Math.log(u1));
    const g1 = mag * Math.cos(2 * Math.PI * u2);
    const g2 = mag * Math.sin(2 * Math.PI * u2);
    const x1 = missX + sx * g1;
    const z1 = missZ + sz * g2;
    if (x1 * x1 + z1 * z1 <= r2) hits++;
    // second draw reuses the pair's other normal, keeping the stream cheap
    const u3 = Math.max(u(), Number.MIN_VALUE);
    const u4 = u();
    const mag2 = Math.sqrt(-2 * Math.log(u3));
    const x2 = missX + sx * mag2 * Math.cos(2 * Math.PI * u4);
    const z2 = missZ + sz * mag2 * Math.sin(2 * Math.PI * u4);
    if (x2 * x2 + z2 * z2 <= r2) hits++;
  }
  const p = hits / n;
  return { p, se: Math.sqrt(Math.max(p * (1 - p), 1e-12) / n) };
}

const c = new Checker(new URL(".", import.meta.url).pathname);

c.fileExists("work/collision-probability.ts", "work/collision-probability.test.ts");
const m = await c.load("./work/collision-probability.ts",
  "collisionProbability", "assumedSigmaKm", "PC_ASSUMPTION_NOTE");
if (!m) process.exit(c.report());

const Pc = (mx: number, mz: number, sx: number, sz: number, r: number) =>
  m.collisionProbability(mx, mz, sx, sz, r) as number;

// ── R3: it is a probability ───────────────────────────────────────────────
const REAL: [number, number, number, number, number][] = [
  [0.5, 0.2, 1.0, 1.0, 0.02],
  [0.0, 0.0, 0.3, 0.8, 0.05],
  [2.0, -1.5, 1.2, 0.6, 0.01],
  [0.05, 0.0, 0.5, 0.5, 0.1],
];
c.custom("every result is a probability in [0, 1]", () =>
  REAL.every(([a, b, d, e, f]) => {
    const p = Pc(a, b, d, e, f);
    return Number.isFinite(p) && p >= 0 && p <= 1;
  }));

// ── The Monte Carlo comparison ────────────────────────────────────────────
for (const [mx, mz, sx, sz, r] of REAL) {
  const { p, se } = monteCarloPc(mx, mz, sx, sz, r);
  const tol = Math.max(4 * se, 1e-7);
  c.closeTo(
    `Pc(miss=[${mx}, ${mz}] sigma=[${sx}, ${sz}] R=${r}) matches Monte Carlo ` +
      `(${(4_000_000).toExponential(0)} samples, 4 s.e. = ${tol.toExponential(2)})`,
    Pc(mx, mz, sx, sz, r), p, tol
  );
}

// ── R4: the limits ────────────────────────────────────────────────────────
//
// These go through `custom` rather than `closeTo` because closeTo evaluates its
// argument eagerly, so an implementation that THROWS where it should return a
// value escapes the Checker entirely and takes the process down with a stack
// trace. Measured: a mutant rejecting radiusKm === 0 produced exit 1 with zero
// FAIL lines and an uncaught RangeError. govern hands the gate's text to the
// next tier as the thing to fix, and a stack trace from the harness tells it
// nothing about the code.
c.custom("Pc -> 1 as the hard-body radius grows", () =>
  Math.abs(Pc(0.5, 0.2, 1, 1, 500) - 1) < 1e-6);
c.custom("Pc = 0 at zero radius (R4), and the call does not throw", () =>
  Pc(0.5, 0.2, 1, 1, 0) === 0);
c.monotone("Pc strictly increases with radius",
  (r) => Pc(0.5, 0.2, 1, 1, r), [0.001, 0.01, 0.05, 0.2, 1, 3], "increasing");
c.monotone("Pc strictly decreases with miss distance",
  (d) => Pc(d, 0, 1, 1, 0.05), [0, 0.5, 1, 2, 4], "decreasing");
c.discriminates("Pc actually varies with miss distance",
  (d) => Pc(d, 0, 1, 1, 0.05), [0, 1, 2, 4], 1e-6);

// A note for whoever mutation-tests this next: flipping `- missXKm` to
// `+ missXKm` in the quadrature is an EQUIVALENT MUTANT and will survive. It
// must. The disk is centred on the origin and the Gaussian is symmetric in
// each axis, so integrating about -missX gives an identical result — which is
// precisely the property the check below asserts. A gate cannot both require
// this symmetry and detect a change that only exploits it.
c.custom("Pc is unchanged when the miss vector's signs flip", () => {
  const base = Pc(1.3, -0.7, 0.9, 1.4, 0.03);
  return [[-1.3, -0.7], [1.3, 0.7], [-1.3, 0.7]].every(
    ([a, b]) => Math.abs(Pc(a, b, 0.9, 1.4, 0.03) - base) < 1e-12
  );
});

// ── R5: dilution — the property an implementation is likeliest to miss ────
{
  // For a fixed non-zero miss, Pc rises then falls as sigma grows. An
  // implementation monotone in sigma is wrong, and would pass every other
  // check in this file.
  const miss = 1.0;
  const sigmas = [0.05, 0.1, 0.2, 0.35, 0.5, 0.7, 1.0, 1.5, 2.5, 5, 10];
  const ps = sigmas.map((s) => Pc(miss, 0, s, s, 0.02));
  const peak = ps.indexOf(Math.max(...ps));
  c.custom(`Pc peaks at an interior sigma, not at an endpoint ` +
    `(max at sigma=${sigmas[peak]} of ${sigmas[0]}..${sigmas[sigmas.length - 1]})`,
    () => peak > 0 && peak < sigmas.length - 1);
  c.custom(`the peak sits near sigma ~ the miss distance (${miss} km)`,
    () => sigmas[peak] >= 0.3 * miss && sigmas[peak] <= 3 * miss);
  c.custom("Pc falls away on BOTH sides of the peak — dilution is real, not " +
    "a sampling artefact", () =>
    ps[0] < ps[peak] && ps[ps.length - 1] < ps[peak]);

  // And the turning point agrees with Monte Carlo, so it is a property of the
  // physics rather than of the quadrature.
  const mc = sigmas.map((s) => monteCarloPc(miss, 0, s, s, 0.02, 1_000_000).p);
  const mcPeak = mc.indexOf(Math.max(...mc));
  c.custom(`Monte Carlo peaks at the same sigma (${sigmas[mcPeak]})`,
    () => Math.abs(mcPeak - peak) <= 1);
}

// ── R6: the assumed sigma ─────────────────────────────────────────────────
c.monotone("assumed sigma grows with TLE age",
  (h) => m.assumedSigmaKm(h) as number, [0, 1, 6, 24, 72], "increasing");
c.custom("assumed sigma is strictly positive at epoch", () =>
  (m.assumedSigmaKm(0) as number) > 0);
c.discriminates("assumed sigma actually varies",
  (h) => m.assumedSigmaKm(h) as number, [0, 12, 48], 1);

// ── R7: the caveat travels with the number ────────────────────────────────
// These are not maths checks. They are the reason this slice is allowed to
// exist at all: the probability is real arithmetic over an invented input, and
// the only thing preventing that from becoming a false claim is that the
// caveat is attached to the module and cannot be dropped by a caller.
c.custom("PC_ASSUMPTION_NOTE is a non-trivial string", () =>
  typeof m.PC_ASSUMPTION_NOTE === "string" && m.PC_ASSUMPTION_NOTE.length > 40);
c.custom("PC_ASSUMPTION_NOTE says the uncertainty is ASSUMED", () =>
  /assumed/i.test(m.PC_ASSUMPTION_NOTE as string));
c.custom("PC_ASSUMPTION_NOTE does not claim to be operational", () =>
  !/operational(?!\s*(use|conjunction assessment)?[^.]*\bnot\b)/i.test(
    (m.PC_ASSUMPTION_NOTE as string).replace(/not operational/gi, "")
  ) || /not\s+(an\s+)?operational|indicative/i.test(m.PC_ASSUMPTION_NOTE as string));

// ── R8: malformed input ───────────────────────────────────────────────────
c.throws("no arguments throws RangeError", () => m.collisionProbability(), /RangeError/);
c.throws("NaN miss throws", () => m.collisionProbability(NaN, 0, 1, 1, 0.1), /RangeError/);
c.throws("zero sigmaX throws", () => m.collisionProbability(0, 0, 0, 1, 0.1), /RangeError/);
c.throws("zero sigmaZ throws", () => m.collisionProbability(0, 0, 1, 0, 0.1), /RangeError/);
c.throws("negative sigma throws", () => m.collisionProbability(0, 0, -1, 1, 0.1), /RangeError/);
c.throws("negative radius throws", () => m.collisionProbability(0, 0, 1, 1, -0.1), /RangeError/);
c.throws("negative TLE age throws", () => m.assumedSigmaKm(-1), /RangeError/);
c.custom("a radius of exactly zero is VALID and returns 0 — the guard rejects " +
  "negatives without rejecting the boundary", () => Pc(0, 0, 1, 1, 0) === 0);

process.exit(c.report());

