"""Deterministic gate for the logstat slice. No model is involved.

Checks a reviewer could write WITHOUT knowing the right answer. Notably absent:
any assertion about what the statistics should BE — that needs an oracle, and a
gate that encodes the answer is a tautology. Catching a wrong VALUE is the model
gate's job; this layer catches wrong SHAPE and violated invariants.
"""
import sys, os, pathlib

# A slice lives wherever you put it, so find the library rather than assuming a
# relative depth. install.sh puts it in ~/.local/lib/dcode-stack.
for _p in (os.environ.get("DCODE_STACK_LIB"),
           pathlib.Path.home() / ".local/lib/dcode-stack",
           pathlib.Path(__file__).resolve().parents[2] / "lib"):
    if _p and pathlib.Path(_p).is_dir():
        sys.path.insert(0, str(_p))
        break
from invariants import Checker

c = Checker("python3 logstat.py data/server.log", cwd="work")

c.file_exists("logstat.py", "test_logstat.py")
c.tests_pass("python3 -m pytest -q")
c.json_output()
c.required_keys("total_valid", "malformed", "error_rate_pct", "top3_ips", "p95_ms")

# every input line must land in exactly one bucket — needs no oracle
c.conservation("total_valid", "malformed", total=300)

c.is_int("total_valid")
c.non_negative("malformed")
c.in_range("error_rate_pct", 0, 100)
c.is_list("top3_ips", length=3)
c.positive("p95_ms")
c.idempotent()
c.survives("python3 logstat.py /dev/null", "an empty log")

raise SystemExit(c.report())

